        String name = "\"companyName\": \"Tecnosul Ltda\",";
        String passport = "\"guestPassport\": \"X1234567\",";
        String country = "\"guestCountry\": \"United Kingdom\",";
        String cpf = "\"guestCpf\": \"111.222.333-44\",";
        for (String invalid : new String[] {"", cnpj, name, passport, country, cnpj + passport + country,
                cpf + cnpj + name, cpf + passport + country, cnpj + name + country}) {
            HttpResponse<String> response = post("/reservations", reservationWith(invalid));
            assertEquals(400, response.statusCode(), invalid);
            assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
        }

        HttpResponse<String> company = post("/reservations", reservationWith(cnpj + name));
        assertEquals(201, company.statusCode());
        JsonNode created = json.readTree(company.body());
        assertEquals("Tecnosul Ltda", created.get("companyName").asText());
        assertTrue(created.get("guestCpf").isNull());
        assertTrue(created.get("guestPassport").isNull());

        long id = created.get("id").asLong();
        post("/reservations/" + id + "/confirmation", "");
        JsonNode document = json.readTree(get("/reservations/" + id + "/document").body());
        assertEquals("Fatura de hospedagem", document.get("title").asText());
        assertEquals("12.345.678/0001-90", document.get("companyCnpj").asText());
        assertTrue(document.get("guestCpf").isNull());
        assertTrue(document.get("guestCountry").isNull());
        assertTrue(document.get("text").asText().contains("ISS retido (5%): R$ 38,99"));

        HttpResponse<String> foreigner = post("/reservations",
                reservationWith(passport + country).replace("2027-07-1", "2027-08-1"));
        assertEquals(201, foreigner.statusCode());
        assertEquals("X1234567", json.readTree(foreigner.body()).get("guestPassport").asText());
    }
